const transactionsHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Transaction history · s/watcher</title><style nonce="{{.CSPNonce}}">
:root{color-scheme:dark;--bg:#0b0d10;--card:#151920;--ink:#f4f1ea;--muted:#9da5b2;--gold:#f2a900;--line:#29303a;--bad:#ff746c;--good:#72d69b;--field:#0e1116;--button-ink:#17120a}.theme-cypherpunk{--bg:#120d18;--card:#211529;--ink:#fff1fa;--muted:#c2a8c8;--gold:#ff4fa3;--line:#49314f;--bad:#ff7676;--good:#70e0b0;--field:#190f20;--button-ink:#240616}.theme-arctic{--bg:#09121b;--card:#132231;--ink:#edf8ff;--muted:#9bb8cc;--gold:#69c3ff;--line:#29445a;--bad:#ff8585;--good:#72d9b0;--field:#0d1924;--button-ink:#071724}.theme-forest{--bg:#0c130e;--card:#172219;--ink:#f1f5e9;--muted:#a9b59d;--gold:#d1b85b;--line:#354333;--bad:#f17d73;--good:#7bd398;--field:#111a13;--button-ink:#211c08}.theme-paper{color-scheme:light;--bg:#f5f0e6;--card:#fffdf7;--ink:#26231d;--muted:#6b655a;--gold:#d97706;--line:#d8cfbf;--bad:#b42318;--good:#18794e;--field:#f8f3ea;--button-ink:#fff}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,sans-serif}.wrap{width:min(1120px,94vw);margin:42px auto}.top,.toolbar,.transaction-head,.pager{display:flex;justify-content:space-between;align-items:center;gap:16px}.top{align-items:flex-start}.controls{display:flex;gap:8px;align-items:center}.tag{color:var(--gold);letter-spacing:.08em;text-transform:uppercase;font-size:.78rem}h1{margin:.15em 0 .1em;font-size:2.25rem}h2{margin:.2em 0}.muted,.summary{color:var(--muted)}a{color:var(--gold)}button,.button,select{display:inline-block;border:1px solid var(--line);border-radius:8px;padding:9px 12px;background:var(--field);color:var(--ink);font:inherit;text-decoration:none}.button,button{cursor:pointer}.signout button{background:transparent;color:var(--muted)}.card,.transaction-card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:20px;margin-top:18px}.wallet-summary{display:flex;justify-content:space-between;gap:20px;align-items:end}.balance{font-size:1.2rem;font-weight:800}.toolbar{margin-top:22px}.sort-form{display:flex;align-items:center;gap:8px;color:var(--muted)}.transaction-card{padding:18px}.transaction-head{align-items:flex-start}.direction{font-weight:800;text-transform:capitalize}.direction.received{color:var(--good)}.direction.sent{color:var(--bad)}.amount{font-size:1.05rem;font-weight:800}.details{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:15px 0}.detail{padding:9px 10px;border-radius:8px;background:var(--field)}.detail span{display:block;color:var(--muted);font-size:.72rem;text-transform:uppercase}.txid{font-family:ui-monospace,monospace;font-size:.8rem;word-break:break-all}.tx-link{color:var(--muted);text-decoration:underline;text-underline-offset:2px}.state{color:var(--muted);font-size:.82rem}.masked{font-family:"Noto Sans Symbols 2","Segoe UI Symbol",ui-monospace,monospace;letter-spacing:.12em}.badge{display:inline-block;margin:7px 6px 0 0;padding:3px 7px;border-radius:999px;background:#d8dadd;color:#17120a;font-size:.7rem;font-weight:800}.badge.rbf{background:#f2b84b}.badge.runes{background:#d4bdf2}.badge.ordinals{background:#f2cf8e}.badge.privacy{background:#bcdced}.op-return{margin-top:9px;padding:7px 9px;border-radius:7px;background:#d8dadd;color:#111;white-space:pre-wrap;overflow-wrap:anywhere}.op-return strong{margin-right:6px}.pager{margin:24px 0}.pager .disabled{visibility:hidden}.empty{padding:42px 10px;text-align:center;color:var(--muted)}
.address-value{font-family:ui-monospace,monospace;font-size:.8rem;word-break:break-all}.copy-address{display:block;border:0;border-radius:3px;padding:0;background:transparent;color:var(--ink);text-align:left;cursor:copy}.copy-address:hover{color:var(--gold)}.copy-address:focus-visible{outline:2px solid var(--gold);outline-offset:3px}.address-amount{font-weight:800;white-space:nowrap}.address-list{margin:12px 0;padding:10px;border-radius:8px;background:var(--field)}.address-line{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:2px 14px;align-items:end}.address-line+.address-line{margin-top:9px}.address-label{grid-column:1/-1;color:var(--muted);font-size:.72rem;text-transform:uppercase}.export-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:16px;padding-top:14px;border-top:1px solid var(--line)}.export-action{padding:7px 10px;color:var(--muted);font-size:.78rem}.export-action:hover{border-color:var(--gold);color:var(--ink)}.export-action:disabled{cursor:wait;opacity:.6}.copy-feedback{position:fixed;left:50%;bottom:24px;z-index:10;transform:translate(-50%,18px);padding:8px 13px;border-radius:999px;background:var(--ink);color:var(--bg);font-weight:800;opacity:0;pointer-events:none;transition:opacity .16s ease,transform .16s ease}.copy-feedback.visible{opacity:1;transform:translate(-50%,0)}
@media(max-width:720px){.top,.wallet-summary,.toolbar,.transaction-head{display:block}.controls{margin-top:14px}.sort-form{margin-top:12px;align-items:stretch}.sort-form select,.sort-form button{min-width:0}.details{grid-template-columns:1fr}.amount{margin-top:7px}.pager{gap:8px}.pager .button{padding:8px}}
</style></head><body class="theme-{{.Theme}}"><main class="wrap">
<header class="top"><div><div class="tag">Transaction history</div><h1>{{.Group.Category}} / {{.Group.Label}}</h1><p class="summary">Every transaction recorded for this watch group.</p></div><div class="controls"><a class="button" href="/">Back to watches</a><form class="signout" method="post" action="/logout"><button>Sign out</button></form></div></header>
<section class="card wallet-summary"><div><div class="tag">Watch summary</div><strong>{{.Group.Addresses}} watched address{{if ne .Group.Addresses 1}}es{{end}}</strong></div><div><div class="tag">Current balance</div><div class="balance {{if .PrivacyMode}}masked{{end}}">{{.Group.DisplayBalance}}</div></div></section>
<div class="toolbar"><div><strong>{{.TotalEvents}}</strong> transaction{{if ne .TotalEvents 1}}s{{end}} · page {{.Page}} of {{.TotalPages}}</div><form class="sort-form" method="get"><label for="transaction-sort">Sort by</label><select id="transaction-sort" name="sort"><option value="newest" {{if eq .SortMode "newest"}}selected{{end}}>Newest first</option><option value="oldest" {{if eq .SortMode "oldest"}}selected{{end}}>Oldest first</option><option value="largest" {{if eq .SortMode "largest"}}selected{{end}}>Largest value</option><option value="smallest" {{if eq .SortMode "smallest"}}selected{{end}}>Smallest value</option><option value="incoming" {{if eq .SortMode "incoming"}}selected{{end}}>Incoming first</option><option value="outgoing" {{if eq .SortMode "outgoing"}}selected{{end}}>Outgoing first</option><option value="mempool" {{if eq .SortMode "mempool"}}selected{{end}}>Mempool first</option><option value="confirmed" {{if eq .SortMode "confirmed"}}selected{{end}}>Confirmed first</option></select><button>Apply</button></form></div>
{{if .Events}}{{range .Events}}<article class="transaction-card"><div class="transaction-head"><div><div class="direction {{.Direction}}">{{if .DetailsPending}}Indexed transaction{{else}}{{.Direction}}{{end}}</div><div class="state">{{if gt .Height 0}}Confirmed · block {{.Height}}{{else}}Unconfirmed · mempool{{end}} · {{.SeenAt.Format "2006-01-02 15:04 UTC"}}</div></div><div class="amount {{if $.PrivacyMode}}masked{{end}}">{{if .DetailsPending}}Details pending{{else}}{{.DisplayAmount}}{{end}}</div></div>{{if not .DetailsPending}}<div class="details"><div class="detail"><span>Received</span><strong class="{{if $.PrivacyMode}}masked{{end}}">{{.DisplayReceived}}</strong></div><div class="detail"><span>Sent</span><strong class="{{if $.PrivacyMode}}masked{{end}}">{{.DisplaySent}}</strong></div><div class="detail"><span>Net change</span><strong class="{{if $.PrivacyMode}}masked{{end}}">{{.DisplayNet}}</strong></div></div>{{if or .DisplaySourceAddressAmounts .DisplaySpentAddressAmounts .DisplayDestinationAddressAmounts}}<div class="address-list">{{range .DisplaySourceAddressAmounts}}<div class="address-line"><span class="address-label">From input address</span>{{if $.PrivacyMode}}<span class="address-value masked">{{.Address}}</span>{{else}}<button type="button" class="address-value copy-address" data-address="{{.Address}}" title="Copy Bitcoin address">{{.Address}}</button>{{end}}<span class="address-amount {{if $.PrivacyMode}}masked{{end}}">{{.Amount}}</span></div>{{end}}{{range .DisplaySpentAddressAmounts}}<div class="address-line"><span class="address-label">From watched address</span>{{if $.PrivacyMode}}<span class="address-value masked">{{.Address}}</span>{{else}}<button type="button" class="address-value copy-address" data-address="{{.Address}}" title="Copy Bitcoin address">{{.Address}}</button>{{end}}<span class="address-amount {{if $.PrivacyMode}}masked{{end}}">{{.Amount}}</span></div>{{end}}{{range .DisplayDestinationAddressAmounts}}<div class="address-line"><span class="address-label">To address</span>{{if $.PrivacyMode}}<span class="address-value masked">{{.Address}}</span>{{else}}<button type="button" class="address-value copy-address" data-address="{{.Address}}" title="Copy Bitcoin address">{{.Address}}</button>{{end}}<span class="address-amount {{if $.PrivacyMode}}masked{{end}}">{{.Amount}}</span></div>{{end}}</div>{{end}}{{end}}<div class="txid">{{if and (not $.PrivacyMode) $.MempoolURLs}}<a class="tx-link" data-txid="{{.TxID}}">{{.DisplayTxID}}</a>{{else}}{{.DisplayTxID}}{{end}}</div>{{if .DetailsPending}}<span class="badge">Full details will be retried during the next local Electrs scan</span>{{end}}{{if and (not .DetailsPending) (eq .Height 0) .Replaceable (eq .Direction "received")}}<span class="badge rbf">Replaceable — do not treat as final until confirmed</span>{{end}}{{if .Runestone}}<span class="badge runes">Runes · runestone detected</span>{{end}}{{if .Inscriptions}}<span class="badge ordinals">Ordinals · {{.Inscriptions}} inscription envelope{{if ne .Inscriptions 1}}s{{end}}</span>{{end}}{{if .ReuseCount}}<span class="badge privacy">Address reused · {{.ReuseCount}} observed receipts</span>{{end}}{{if .SmallDeposit}}<span class="badge privacy">Small deposit · below {{.DisplaySmallDepositThreshold}}</span>{{end}}{{if .CombinedGroups}}<span class="badge privacy">Combined funds from {{.CombinedGroups}} watched wallets</span>{{end}}{{range .OPReturn}}<div class="op-return"><strong>OP_RETURN</strong>{{.}}</div>{{end}}</article>{{end}}{{else}}<section class="card empty">No transactions were returned by your local Electrs service for this watch.</section>{{end}}
<nav class="pager" aria-label="Transaction pages">{{if .PreviousURL}}<a class="button" href="{{.PreviousURL}}">Previous 100</a>{{else}}<span class="button disabled">Previous 100</span>{{end}}<span>Page {{.Page}} of {{.TotalPages}}</span>{{if .NextURL}}<a class="button" href="{{.NextURL}}">Next 100</a>{{else}}<span class="button disabled">Next 100</span>{{end}}</nav>
<script nonce="{{.CSPNonce}}">
const transactionWatchName=(document.querySelector('.top h1')?.textContent||'Saved watch').trim();
function cleanExportText(element){return(element?.textContent||'').trim().replace(/\s+/g,' ')}
function transactionExportLines(card){const lines=['s/watcher','Bitcoin transaction','','Watch: '+transactionWatchName,'Activity: '+cleanExportText(card.querySelector('.direction')),'State: '+cleanExportText(card.querySelector('.state')),'Amount: '+cleanExportText(card.querySelector('.amount'))];card.querySelectorAll('.detail').forEach(detail=>lines.push(cleanExportText(detail.querySelector('span'))+': '+cleanExportText(detail.querySelector('strong'))));card.querySelectorAll('.address-line').forEach(row=>lines.push(cleanExportText(row.querySelector('.address-label'))+': '+cleanExportText(row.querySelector('.address-value'))+' — '+cleanExportText(row.querySelector('.address-amount'))));const txid=cleanExportText(card.querySelector('.txid'));if(txid)lines.push('Transaction ID: '+txid);const localLink=card.querySelector('.tx-link');if(localLink?.href)lines.push('Local Mempool: '+localLink.href);card.querySelectorAll('.badge').forEach(badge=>lines.push('Notice: '+cleanExportText(badge)));card.querySelectorAll('.op-return').forEach(item=>lines.push('OP_RETURN: '+cleanExportText(item).replace(/^OP_RETURN\s*/i,'')));lines.push('','Generated locally by s/watcher');return lines}
function transactionExportText(card){return transactionExportLines(card).join('\n')}
async function writeExportClipboard(value){if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(value);return}const field=document.createElement('textarea');field.value=value;field.setAttribute('readonly','');field.style.position='fixed';field.style.opacity='0';document.body.appendChild(field);field.select();const copied=document.execCommand('copy');field.remove();if(!copied)throw new Error('copy failed')}
function canvasLines(context,text,maxWidth){if(!text)return[''];const words=text.split(' '),lines=[];let current='';for(const word of words){if(context.measureText(word).width>maxWidth){if(current){lines.push(current);current=''}let part='';for(const character of word){if(context.measureText(part+character).width>maxWidth&&part){lines.push(part);part=character}else part+=character}current=part;continue}const next=current?current+' '+word:word;if(context.measureText(next).width>maxWidth&&current){lines.push(current);current=word}else current=next}if(current)lines.push(current);return lines}
async function saveTransactionImage(card){const source=transactionExportLines(card).slice(3),style=getComputedStyle(document.body),colors={background:style.getPropertyValue('--card').trim()||'#151920',ink:style.getPropertyValue('--ink').trim()||'#f4f1ea',muted:style.getPropertyValue('--muted').trim()||'#9da5b2',accent:style.getPropertyValue('--gold').trim()||'#f2a900',line:style.getPropertyValue('--line').trim()||'#29303a'},width=1200,padding=64,maxWidth=width-padding*2,scratch=document.createElement('canvas').getContext('2d');scratch.font='24px system-ui, sans-serif';const wrapped=[];for(const line of source){if(!line){wrapped.push('');continue}wrapped.push(...canvasLines(scratch,line,maxWidth))}const height=Math.max(520,230+wrapped.reduce((total,line)=>total+(line?38:20),0)+90);if(height>28000)throw new Error('transaction image is too tall');const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const context=canvas.getContext('2d');context.fillStyle=colors.background;context.fillRect(0,0,width,height);context.strokeStyle=colors.line;context.lineWidth=3;context.strokeRect(2,2,width-4,height-4);context.fillStyle=colors.accent;context.fillRect(padding,52,58,58);context.fillStyle=colors.background;context.font='900 46px system-ui, sans-serif';context.fillText('/',padding+20,98);context.fillStyle=colors.ink;context.font='800 42px system-ui, sans-serif';context.fillText('s/watcher',padding+78,96);context.fillStyle=colors.muted;context.font='22px system-ui, sans-serif';context.fillText('Private Bitcoin transaction record',padding,148);context.strokeStyle=colors.line;context.beginPath();context.moveTo(padding,178);context.lineTo(width-padding,178);context.stroke();let y=226;for(const line of wrapped){if(!line){y+=20;continue}const separator=line.indexOf(':');if(separator>0&&separator<28){const label=line.slice(0,separator+1),value=line.slice(separator+1);context.font='700 24px system-ui, sans-serif';context.fillStyle=colors.muted;context.fillText(label,padding,y);const offset=context.measureText(label+' ').width;context.font='24px system-ui, sans-serif';context.fillStyle=colors.ink;context.fillText(value,padding+offset,y)}else{context.font='24px system-ui, sans-serif';context.fillStyle=colors.ink;context.fillText(line,padding,y)}y+=38}context.strokeStyle=colors.line;context.beginPath();context.moveTo(padding,height-66);context.lineTo(width-padding,height-66);context.stroke();context.fillStyle=colors.muted;context.font='20px system-ui, sans-serif';context.fillText('Generated locally by s/watcher',padding,height-30);const blob=await new Promise((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error('image encoding failed')),'image/png'));const txid=cleanExportText(card.querySelector('.txid')),name=/^[0-9a-f]{64}$/i.test(txid)?'swatcher-'+txid.slice(0,12)+'.png':'swatcher-transaction.png',link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}
document.querySelectorAll('.transaction-card').forEach(card=>{const actions=document.createElement('div'),copy=document.createElement('button'),image=document.createElement('button');actions.className='export-actions';copy.type='button';copy.className='export-action copy-transaction';copy.textContent='Copy text';copy.setAttribute('aria-label','Copy this transaction as formatted text');image.type='button';image.className='export-action save-transaction';image.textContent='Save image';image.setAttribute('aria-label','Save this transaction as a branded PNG image');actions.append(copy,image);card.append(actions);copy.addEventListener('click',async()=>{try{await writeExportClipboard(transactionExportText(card));showCopyFeedback('Transaction copied')}catch(_){showCopyFeedback('Could not copy transaction')}});image.addEventListener('click',async()=>{image.disabled=true;try{await saveTransactionImage(card);showCopyFeedback('Transaction image saved')}catch(_){showCopyFeedback('Could not save transaction image')}finally{image.disabled=false}})})
</script>
</main><div id="copy-feedback" class="copy-feedback" role="status" aria-live="polite"></div><div id="mempool-urls" hidden>{{range .MempoolURLs}}<span data-url="{{.}}"></span>{{end}}</div><script nonce="{{.CSPNonce}}">const mempoolURLs=[...document.querySelectorAll('#mempool-urls [data-url]')].map(item=>item.dataset.url),usingTor=location.hostname.endsWith('.onion'),mempoolBase=mempoolURLs.find(value=>{try{return new URL(value).hostname.endsWith('.onion')===usingTor}catch(_){return false}})||mempoolURLs[0];if(mempoolBase){document.querySelectorAll('.tx-link[data-txid]').forEach(link=>{link.href=mempoolBase.replace(/\/$/,'')+'/tx/'+encodeURIComponent(link.dataset.txid);link.target='_blank';link.rel='noopener noreferrer';link.title='Open transaction in your local Mempool service'})}const copyFeedback=document.getElementById('copy-feedback');let copyFeedbackTimer;function showCopyFeedback(message){copyFeedback.textContent=message;copyFeedback.classList.add('visible');clearTimeout(copyFeedbackTimer);copyFeedbackTimer=setTimeout(()=>copyFeedback.classList.remove('visible'),1800)}async function copyAddress(value){if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(value);return}const field=document.createElement('textarea');field.value=value;field.setAttribute('readonly','');field.style.position='fixed';field.style.opacity='0';document.body.appendChild(field);field.select();const copied=document.execCommand('copy');field.remove();if(!copied)throw new Error('copy failed')}document.querySelectorAll('.copy-address[data-address]').forEach(button=>button.addEventListener('click',async()=>{try{await copyAddress(button.dataset.address);showCopyFeedback('Address copied')}catch(_){showCopyFeedback('Could not copy address')}}))</script></body></html>`
